verus! {
    use std::vec::Vec;

    // Function to return the value at the diagonal position
    fn diag_val(i: int, j: int) -> (result: f64) {
        // If i equals j, return 1.0, otherwise return 0.0
        if i == j {
            1.0
        } else {
            0.0
        }
    }

    // Function to create an n x n identity matrix
    fn identity(n: usize) -> (result: Vec<Vec<f64>>) {
        // Ensure n is non-negative
        requires(n >= 0);
        
        // Create a vector of vectors to hold the identity matrix
        let mut matrix: Vec<Vec<f64>> = Vec::new();
        
        // Loop to create each row of the matrix
        for i in 0..n {
            // Create a new row
            let mut row: Vec<f64> = Vec::new();
            // Loop to fill the row
            for j in 0..n {
                // Push the diagonal value into the row
                row.push(diag_val(i as int, j as int));
            }
            // Push the completed row into the matrix
            matrix.push(row);
        }
        
        // Ensure the matrix has the correct dimensions
        ensures(matrix.len() == n);
        for i in 0..n {
            ensures(matrix[i].len() == n);
        }
        
        // Return the constructed identity matrix
        matrix
    }
}